import React from "react";
import { Link } from "react-router-dom";
import Navbar from "../components/Navbar";
import "./Home.css";

function Home() {
  return (
    <>
      <Navbar />

      <div className="home">
        <div className="hero">
          <h1>Track Your Orders</h1>
          <p>Fast. Secure. Reliable.</p>

          <div className="hero-buttons">
            <Link to="/create-order" className="btn primary">
              Create Order
            </Link>

            <Link to="/track-order" className="btn secondary">
              Track Order
            </Link>
          </div>
        </div>
      </div>
    </>
  );
}

export default Home;
